import{_ as s,a as l,b as r}from"./chunks/out-of-space.D_ukUxGE.js";import{_ as i,C as d,o as h,c as u,a2 as a,j as e,a as t,E as c}from"./chunks/framework.C0pL2NcE.js";const b="/colony-flow-sand/docs/assets/sand-board.BUt3SG_m.png",p="/colony-flow-sand/docs/assets/frozen.Ael2PbzG.png",m="/colony-flow-sand/docs/assets/conveyor.Bz2VyGqe.png",f="/colony-flow-sand/docs/assets/nests.DwkF3V-S.png",g="/colony-flow-sand/docs/assets/hud.DXtPn4mv.png",P=JSON.parse('{"title":"1. Core gameplay","description":"","frontmatter":{"pageClass":"gdd-wide"},"headers":[],"relativePath":"gdd/core-gameplay.md","filePath":"gdd/core-gameplay.md"}'),w={name:"gdd/core-gameplay.md"},y={class:"gdd-table"},v={id:"obstacle-frozen"};function k(_,o,x,T,S,A){const n=d("Badge");return h(),u("div",null,[o[5]||(o[5]=a('<h1 id="_1-core-gameplay" tabindex="-1">1. Core gameplay <a class="header-anchor" href="#_1-core-gameplay" aria-label="Permalink to &quot;1. Core gameplay&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Date</th><th>Detail</th><th>Author</th></tr></thead><tbody><tr><td>2026-10-27</td><td>Initial design (GDD created)</td><td>Tuan Dinh Duc</td></tr><tr><td>2026-11-03</td><td>Rewritten in the core gameplay format: an overview, then one table per screen zone</td><td>Tuan Dinh Duc</td></tr></tbody></table><p>Every change to the game, build by build, is in the <a href="./changelog">Changelog</a>. Sizes and positions are in world pixels on the 1080 × 1920 portrait game screen; every number comes from the current code (<code>src/game/layout.ts</code>, <code>src/game/sim.ts</code>).</p><h2 id="i-overview" tabindex="-1">I. Overview <a class="header-anchor" href="#i-overview" aria-label="Permalink to &quot;I. Overview&quot;">​</a></h2><table class="gdd-table"><thead><tr><th style="width:30%;">Fakescreen</th><th>Details</th><th style="width:22%;">Demo</th></tr></thead><tbody><tr><td><img src="'+s+'" alt="The game screen"></td><td><p><b>How to play:</b></p><ul><li>A picture made of coloured sand fills a frame. The player swipes the sand to set it free.</li><li>Freed sand falls into the funnel under the frame and down a hole, where every 64 grains of one colour are pressed into a block.</li><li>The blocks come out of the gate under the frame onto a conveyor that runs round and round.</li><li>Ant nests wait under the conveyor, each for blocks of one colour. When a block of its colour passes, an ant walks out, takes it and carries it home, and the number on the nest counts down.</li><li>A full nest pops and the next nest in its column moves up.</li><li>The tension: the conveyor has 30 slots. Releasing a colour no front nest wants fills it up.</li></ul><p><b>Win:</b></p><ul><li>Every nest has all its blocks.</li></ul><p><b>Lose:</b></p><ul><li>All 30 conveyor slots hold a block and none of them can go into a nest any more (no front nest wants a colour on the belt, no ant is on its way and no nest is popping) for more than 0.35 s: <b>Out of Space!</b></li></ul><p><b>Session:</b> a level takes about 30 to 150 seconds. The last level reached is remembered.</p></td><td><p><b>Play:</b> <a href="https://tuandds.github.io/colony-flow-sand/demo/" target="_blank">demo</a></p><p><b>Gameplay reels</b> (the game plays itself): <a href="https://tuandds.github.io/colony-flow-sand/demo/?demo=drops30" target="_blank">drops30</a>, <a href="https://tuandds.github.io/colony-flow-sand/demo/?demo=mix60" target="_blank">mix60</a>; see <a href="../guide/demo-videos">Demo Videos</a></p><p><b>Level Editor:</b> <a href="https://tuandds.github.io/colony-flow-sand/demo/editor.html" target="_blank">editor</a></p></td></tr></tbody></table><p><strong>Screen layout</strong> (top to bottom):</p><table tabindex="0"><thead><tr><th>Zone</th><th>Share of the screen height</th><th>Position (y)</th></tr></thead><tbody><tr><td><a href="#_4-hud-boosters">4. HUD &amp; boosters</a></td><td>about 14 %</td><td>0 – 270</td></tr><tr><td><a href="#_1-sand-board-funnel">1. Sand board &amp; funnel</a></td><td>about 57 %</td><td>279 – 1378</td></tr><tr><td><a href="#_2-conveyor">2. Conveyor</a></td><td>about 12 %</td><td>1380 – 1604</td></tr><tr><td><a href="#_3-nests-ants">3. Nests &amp; ants</a></td><td>about 17 % (two rows and a half on screen)</td><td>1604 – 1920</td></tr></tbody></table><h2 id="_1-sand-board-funnel" tabindex="-1">1. Sand board &amp; funnel <a class="header-anchor" href="#_1-sand-board-funnel" aria-label="Permalink to &quot;1. Sand board &amp; funnel&quot;">​</a></h2>',8)),e("table",y,[o[4]||(o[4]=e("thead",null,[e("tr",null,[e("th",{style:{width:"30%"}},"Fakescreen"),e("th",null,"Details")])],-1)),e("tbody",null,[o[3]||(o[3]=e("tr",null,[e("td",null,[e("img",{src:b,alt:"The sand board and its funnel"})]),e("td",null,[e("p",null,[e("b",null,"Structure:"),t(" about 57 % of the screen height: the picture frame and its funnel, one piece of art ("),e("code",null,"img/frame.png"),t(").")]),e("ul",null,[e("li",null,[e("b",null,"Board:"),t(" the frame's inside, 824 × 776 px at (128, 330), under the frame's grey top band (shaded as a wall under the raised white rim). Its corners are rounded like the art's (the top corners of the light blue, and the bottom corners where they begin to curve into the funnel); no sand goes there.")]),e("li",null,[e("b",null,"Picture:"),t(" up to 188 × 176 grains (22 cells tall; a cell is 8 × 8 grains, 35 px; a grain is about 4.4 px). The scale is the same in every level; a smaller picture sits centred. A full frame is exactly 517 blocks.")]),e("li",null,[e("b",null,"Colours:"),t(" each level uses its own few colours from the Colour Bank (4 to 6 in the current levels, up to 12).")]),e("li",null,[e("b",null,"Inner stroke:"),t(" a dark stroke runs along the inside's edge, from under the grey band down the sides and the funnel to the spout. It is drawn over the sand, so it shows even where a picture fills the frame.")]),e("li",null,[e("b",null,"Funnel:"),t(" as wide as the board at the top (824 px), its sides curve in, as the art's do, to the hole (about 75 px wide) 183 px under the board. The spout ends over the "),e("b",null,"gate"),t(" at the bottom of the frame, just above the conveyor.")])]),e("p",null,[e("b",null,"Sand:")]),e("ul",null,[e("li",null,[t("Sand is "),e("b",null,"fixed"),t(" until swiped. A swipe frees the sand within 38.5 px of the finger (1.1 cells); freed sand is "),e("b",null,"loose"),t(" and drawn 22 % brighter.")]),e("li",null,"Loose sand falls with gravity 0.09 grains/step² up to 3.5 grains/step, at 110 steps per second. Blocked below, it slides down-left or down-right; on gentle slopes it creeps sideways toward a drop within 2 grains, with friction 0.82."),e("li",null,"Small or thin islands of fixed sand (48 grains or fewer, or narrower than 4 grains) come loose by themselves every 0.5 s."),e("li",null,[e("b",null,"The picture plays as drawn:"),t(" no grain is added, removed or recoloured when a level loads. Every 64 grains of a colour make a block, and a colour's leftover grains make its last block, so each colour makes its grains ÷ 64 blocks, rounded up.")])]),e("p",null,[e("b",null,"Funnel and hole:")]),e("ul",null,[e("li",null,[t("The board and the funnel are "),e("b",null,"one sand pile"),t(": the same grains fall from the board straight on into the funnel. Its curved sides are walls that loose sand slides down toward the hole.")]),e("li",null,[e("b",null,"First down, first out:"),t(" grains are numbered as they come into the funnel and move oldest first; the hole takes the oldest grains first. Sand comes out within about 3 blocks of the order it came down in.")]),e("li",null,"The hole takes 540 grains per second, but only while no finished block is waiting in it. Each colour is pressed on its own: a colour's sand waits under the hole until it has 64 grains (or its last grain is down)."),e("li",null,"When the hole is plugged or slower than the sand coming in, the funnel fills up and the sand piles back up into the board.")]),e("p",null,[e("b",null,"Position:"),t(" centred under the HUD; its gate sits just above the conveyor.")])])],-1)),e("tr",null,[o[2]||(o[2]=e("td",null,[e("img",{src:p,alt:"A Frozen area on level_6, counting 20"})],-1)),e("td",null,[e("h3",v,[o[0]||(o[0]=t("Obstacle: Frozen ",-1)),c(n,{type:"tip",text:"Live"})]),o[1]||(o[1]=a("<p>A patch of the picture locked under a sheet of ice, with a number on it.</p><ul><li><b>Shape:</b> a square/rectangle or a circle/ellipse, placed in picture grains (<code>frozen</code> in the level: <code>shape</code> <code>rect</code> or <code>circle</code>, <code>x</code>, <code>y</code>, <code>w</code>, <code>h</code>, <code>count</code>). A level may have several.</li><li><b>Locked:</b> the sand under the ice cannot be swept and never comes loose by itself (small islands next to it still do). Falling sand cannot enter it, so loose sand piles up on top of it.</li><li><b>Count:</b> the number goes down by 1 each time a nest is removed (a full nest pops and leaves its column). It pops a little each time it changes.</li><li><b>Break:</b> at 0 the ice shatters: its shards fly out and fall, the sheet fades out, and the sand it held becomes ordinary fixed sand that the player can sweep.</li><li><b>Look:</b> frosted pale blue ice with a white rim, light facets and cracks, a soft glow round it; a dark number with a white outline in the middle.</li><li><b>Level Editor:</b> a level&#39;s areas are kept when it is edited and saved, and drawn on the Sand Editor as a dashed outline with ❄ and the count. They are placed in the level data for now (no tool to draw them yet).</li><li><b>In the levels:</b> level_6, one 44 × 44 grain square on the sail, count 20.</li></ul>",2))])])])]),o[6]||(o[6]=a('<h2 id="_2-conveyor" tabindex="-1">2. Conveyor <a class="header-anchor" href="#_2-conveyor" aria-label="Permalink to &quot;2. Conveyor&quot;">​</a></h2><table class="gdd-table"><thead><tr><th style="width:30%;">Fakescreen</th><th>Details</th></tr></thead><tbody><tr><td><img src="'+m+'" alt="The conveyor"></td><td><p><b>Structure:</b> about 12 % of the screen height.</p><ul><li>A loop track: straight runs from x 203 to 877, round ends of radius 50, centred at y 1492. The belt art (<code>img/conveyor.png</code>) sits in a hollow in the wood: a wall round it, dark at the top as if in shadow and light at the bottom.</li><li><b>30 slots</b>, each with a holder (a dark slate square); a block is a 32 px cube.</li><li>A fill gauge in the middle shows how full the belt is (a green bar and a percentage).</li></ul><p><b>Behaviour:</b></p><ul><li>The belt runs at 300 px/s.</li><li>A finished block waits in the gate&#39;s opening until an empty slot passes under it, then drops onto the belt.</li><li>Blocks ride round until an ant takes them. A full belt is not a loss while ants can still take blocks off it (see <a href="#i-overview">Lose</a>).</li></ul><p><b>Position:</b> between the sand board&#39;s gate and the nests.</p></td></tr></tbody></table><h2 id="_3-nests-ants" tabindex="-1">3. Nests &amp; ants <a class="header-anchor" href="#_3-nests-ants" aria-label="Permalink to &quot;3. Nests &amp; ants&quot;">​</a></h2><table class="gdd-table"><thead><tr><th style="width:30%;">Fakescreen</th><th>Details</th></tr></thead><tbody><tr><td><img src="'+f+'" alt="The nests"></td><td><p><b>Structure:</b> about 17 % of the screen height: two rows of nests and the third down to its number; the rest wait below the screen.</p><ul><li><b>Columns:</b> 4 (a level from the Level Editor can have 2 to 6), 172 px apart. Rows are 130 px apart, with 28 px more under the front row.</li><li><b>Nest:</b> a box in its colour showing how many blocks it still needs (a white number with a black stroke). Front nests are full height in a white frame; waiting nests are lower and paler.</li><li><b>Nest sizes:</b> set by hand in the Level Editor, or built by the game from the picture: the blocks are listed in the order the sand naturally comes out, cut into nests of <code>chunk × 2</code> blocks and dealt to the column with the least sand still queued.</li></ul><p><b>Behaviour:</b></p><ul><li>Only the front nest of each column is active (and nests woken by the Activate booster).</li><li>An ant leaves an active nest every 0.12 s while it still needs blocks and a matching block is on the belt. Ants walk at 420 px/s, are 74 px long and carry 26 px cubes.</li><li>Each ant leaves from its own spot on the nest&#39;s top edge (up to ±38 px from the centre) and heads off its block: it aims at a point a random 25–100 % of the way to where it would meet the block, so some ants chase their block and others cut across. Both come from the level&#39;s seeded random numbers, so a recorded play replays the same.</li><li>A full nest pops; the column slides up. Nests never change column.</li></ul><p><b>Position:</b> under the conveyor, to the bottom of the screen.</p></td></tr></tbody></table><h2 id="_4-hud-boosters" tabindex="-1">4. HUD &amp; boosters <a class="header-anchor" href="#_4-hud-boosters" aria-label="Permalink to &quot;4. HUD &amp; boosters&quot;">​</a></h2><table class="gdd-table"><thead><tr><th style="width:30%;">Fakescreen</th><th>Details</th></tr></thead><tbody><tr><td><img src="'+g+'" alt="The HUD and boosters"></td><td><p><b>Structure:</b> about 14 % of the screen height.</p><ul><li><b>Settings button</b> (top left): the pause panel: close (resume), music, sound and vibration switches (kept in the browser), Restart, Home, and a cheat to jump to any level. Vibration buzzes when a nest fills, on a win and on a loss.</li><li><b>Level title:</b> &quot;Level N&quot;.</li><li><b>Boosters:</b> a row of three 126 px buttons under the title, each with 1 use per level on a red badge (a green plus when none are left). They unlock one by one: Activate at level 3, Shuffle at level 6, Fan at level 9; before that the button is grey with a padlock and its level, and tapping it shows &quot;Unlocks at Level N&quot;.</li><li><b>x2:</b> double speed. Once all the sand has fallen off the picture, x2 turns on by itself and the button hides until the next level.</li></ul><p><b>Boosters:</b></p><ul><li><b>Activate</b> (the claw): tap it, then a nest waiting in the second or third row; ants work for that nest too, from where it stands, until it is full. The game holds still while you pick.</li><li><b>Shuffle:</b> the game holds still and the nests pulse; after 0.5 s they trade places at random (each keeps its blocks), sliding to their new places in about 0.5 s. Nests with an ant on its way stay put.</li><li><b>Fan</b> (the ball cannon): the screen dims and the cannon drops into the middle, sucks the conveyor&#39;s blocks into its mouth one by one, then shoots them, 0.2 s apart, into nests of their colour that still have room, upper rows first. The game holds still until the last block lands.</li><li>A booster that would do nothing (nothing to wake, swap or blow) only bounces and keeps its use.</li></ul><p><b>Desktop testing keys:</b> N / P next and previous level, R restart.</p></td></tr></tbody></table><h2 id="_5-result-screens" tabindex="-1">5. Result screens <a class="header-anchor" href="#_5-result-screens" aria-label="Permalink to &quot;5. Result screens&quot;">​</a></h2><table class="gdd-table"><thead><tr><th style="width:30%;">Fakescreen</th><th>Details</th></tr></thead><tbody><tr><td><img src="'+l+'" alt="The win screen"><br><img src="'+r+'" alt="Out of Space"></td><td><p><b>Win:</b> a blue background, &quot;Level N&quot; over the &quot;AMAZING&quot; title, a pile of coins in a glow with turning rays, &quot;+40&quot; coins and confetti. <b>Claim x2</b> (ad badge, 80 coins) and <b>Continue</b> both go on to the next level (no coins or ads yet).</p><p><b>Out of Space!</b> (the conveyor is full): a broken heart and two revives, <b>Free</b> (ad) and <b>900</b> coins. Either one closes the board and the ball cannon clears the belt into the nests (it does not use up the Fan booster), then play goes on. The ✕ gives up.</p><p><b>Level failed:</b> after giving up, a board shows the lives (four hearts and a blank one), the time to the next heart and &quot;Level failed!&quot;; <b>Try Again</b> starts the level over (lives are only shown for now).</p></td></tr></tbody></table>',8))])}const C=i(w,[["render",k]]);export{P as __pageData,C as default};
